solution.solution.cpp:
#include <cstdint>

struct Result { std::uint8_t value; bool zf, sf, cf, of; };

static Result finish(int unsignedTrue, int signedTrue)
{
    const auto value{ static_cast<std::uint8_t>(unsignedTrue) };   // keep the low 8 bits
    return Result{
        value,
        value == 0,
        (value & 0x80) != 0,
        unsignedTrue < 0 || unsignedTrue > 255,
        signedTrue < -128 || signedTrue > 127,
    };
}

Result add8(std::uint8_t a, std::uint8_t b)
{
    return finish(int{ a } + int{ b }, int{ static_cast<std::int8_t>(a) } + int{ static_cast<std::int8_t>(b) });
}

Result sub8(std::uint8_t a, std::uint8_t b)
{
    return finish(int{ a } - int{ b }, int{ static_cast<std::int8_t>(a) } - int{ static_cast<std::int8_t>(b) });
}

unitTests:
static bool flags(const Result& r, bool zf, bool sf, bool cf, bool of) { return r.zf == zf && r.sf == sf && r.cf == cf && r.of == of; }
TEST("signed overflow") { const Result r{ add8(127, 1) }; CHECK_EQ(static_cast<int>(r.value), 0x80); CHECK(flags(r, false, true, false, true)); }
TEST("unsigned overflow to zero") { const Result r{ add8(255, 1) }; CHECK_EQ(static_cast<int>(r.value), 0); CHECK(flags(r, true, false, true, false)); }
TEST("an ordinary add") { const Result r{ add8(20, 22) }; CHECK_EQ(static_cast<int>(r.value), 42); CHECK(flags(r, false, false, false, false)); }
TEST("both overflows") { const Result r{ add8(0x80, 0x80) }; CHECK_EQ(static_cast<int>(r.value), 0); CHECK(flags(r, true, false, true, true)); }
TEST("negative plus negative fits") { const Result r{ add8(0xFF, 0xFF) }; CHECK_EQ(static_cast<int>(r.value), 0xFE); CHECK(flags(r, false, true, true, false)); }
TEST("borrow") { const Result r{ sub8(3, 5) }; CHECK_EQ(static_cast<int>(r.value), 0xFE); CHECK(flags(r, false, true, true, false)); }
TEST("equal values give zero") { const Result r{ sub8(9, 9) }; CHECK(flags(r, true, false, false, false)); }
TEST("signed overflow on subtract") { const Result r{ sub8(0x80, 1) }; CHECK_EQ(static_cast<int>(r.value), 0x7F); CHECK(flags(r, false, false, false, true)); }

